#!/usr/bin/env node
/**
 * Browser hash throughput bench (T15, wave-5 worker C).
 *
 * Measures the REAL browser hashing path: src/web/features/transfers/
 * hash.worker.ts (hash-wasm incremental SHA-256 + MD5 over 1 MiB slices),
 * bundled on the fly by esbuild into a standalone worker file and driven by a
 * generated in-memory Blob — the identical protocol the upload UI uses
 * ({type:"hash", jobId, blob} -> {type:"result", sha256, md5}).
 *
 * Reported per run: wall ms hashing `size-mib` MiB of generated bytes, and
 * input throughput in MiB/s — i.e. bytes on which BOTH digests were produced
 * per second, matching the app's per-file hashing contract.
 *
 * Usage:
 *   node tests/perf/bench-hash.mjs [--browser chromium|firefox|all]
 *       [--size-mib 256] [--slice-mib 1] [--repeat 1] [--json]
 */

import * as esbuild from "esbuild";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { chromium, firefox } from "@playwright/test";
import { parseFlags } from "./lib/pattern.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const MIB = 1024 * 1024;
const ORIGIN = "http://hash-bench.local";

const HELP = `bench-hash.mjs — browser hash-wasm worker throughput (local only)

Options:
  --browser <chromium|firefox|all>  browser engine(s) (default: all)
  --size-mib <n>   generated blob size in MiB (default: 256)
  --slice-mib <n>  hash slice size in MiB (default: 1, the app's HASH_SLICE_BYTES)
  --repeat <n>     repeat per browser (default: 1)
  --json           print the machine-readable result object only
  --help           show this help

The worker file is bundled from the app's real hash.worker.ts; the page is
served over an intercepted Playwright route so the module worker loads
same-origin. Throughput is input bytes per second with sha256+md5 produced
together — the same work the upload path does before init.`;

function die(msg) {
  console.error(`bench-hash: ${msg}`);
  process.exit(2);
}

async function bundleWorker() {
  const result = await esbuild.build({
    entryPoints: [
      path.join(ROOT, "src/web/features/transfers/hash.worker.ts"),
    ],
    bundle: true,
    write: false,
    format: "iife",
    platform: "browser",
    target: "esnext",
    logLevel: "silent",
  });
  return result.outputFiles[0].text;
}

const PAGE_HTML = `<!doctype html><html><body><script type="module">
window.__bench = async (sizeBytes, sliceBytes) => {
  const block = new Uint8Array(1024 * 1024);
  for (let i = 0; i < block.length; i += 1) block[i] = (i * 31 + 7) & 0xff;
  const parts = [];
  let remaining = sizeBytes;
  while (remaining > 0) {
    const n = Math.min(block.length, remaining);
    parts.push(block.slice(0, n));
    remaining -= n;
  }
  const blob = new Blob(parts);
  const worker = new Worker("/hash.worker.js");
  try {
    const t0 = performance.now();
    const result = await new Promise((resolve, reject) => {
      worker.onmessage = (event) => {
        const msg = event.data;
        if (msg.type === "result") resolve(msg);
        else if (msg.type === "error") reject(new Error(msg.message));
      };
      worker.onerror = (event) => reject(new Error(event.message));
      worker.postMessage({ type: "hash", jobId: "bench", blob, sliceBytes });
    });
    return {
      ms: performance.now() - t0,
      sha256: result.sha256,
      md5: result.md5,
      bytes: sizeBytes,
    };
  } finally {
    worker.terminate();
  }
};
</script></body></html>`;

async function runBrowser(kind, workerJs, sizeBytes, sliceBytes, repeat) {
  const launcher = kind === "firefox" ? firefox : chromium;
  const browser = await launcher.launch(
    kind === "chromium" ? { channel: "chrome" } : {},
  );
  try {
    const page = await browser.newPage();
    await page.route(`${ORIGIN}/**`, (route) => {
      const { pathname } = new URL(route.request().url());
      if (pathname === "/") {
        return route.fulfill({
          status: 200,
          contentType: "text/html",
          body: PAGE_HTML,
        });
      }
      if (pathname === "/hash.worker.js") {
        return route.fulfill({
          status: 200,
          contentType: "text/javascript",
          body: workerJs,
        });
      }
      return route.fulfill({ status: 404, body: "not found" });
    });
    await page.goto(`${ORIGIN}/`);
    const runs = [];
    for (let i = 0; i < repeat; i += 1) {
      runs.push(
        await page.evaluate(
          ([bytes, slice]) => window.__bench(bytes, slice),
          [sizeBytes, sliceBytes],
        ),
      );
    }
    return runs;
  } finally {
    await browser.close();
  }
}

async function main() {
  const flags = parseFlags(process.argv.slice(2), {
    browser: "all",
    "size-mib": "256",
    "slice-mib": "1",
    repeat: "1",
    json: false,
  });
  if (flags.help) {
    console.log(HELP);
    return;
  }
  const sizeBytes = Number(flags["size-mib"]) * MIB;
  const sliceBytes = Number(flags["slice-mib"]) * MIB;
  const repeat = Number(flags.repeat);
  if (!(sizeBytes > 0) || !(sliceBytes > 0) || !(repeat >= 1)) {
    die("--size-mib/--slice-mib must be > 0 and --repeat >= 1");
  }
  const browsers =
    flags.browser === "all" ? ["chromium", "firefox"] : [flags.browser];
  for (const b of browsers) {
    if (!["chromium", "firefox"].includes(b)) {
      die(`unknown --browser ${b} (chromium|firefox|all)`);
    }
  }

  const workerJs = await bundleWorker();
  const results = {};
  for (const kind of browsers) {
    const runs = await runBrowser(kind, workerJs, sizeBytes, sliceBytes, repeat);
    results[kind] = runs.map((r) => ({
      bytes: r.bytes,
      wallMs: r.ms,
      throughputMiBs: r.bytes / MIB / (r.ms / 1000),
      sha256: r.sha256,
      md5: r.md5,
    }));
    if (!flags.json) {
      for (const [i, r] of results[kind].entries()) {
        console.error(
          `[${kind}#${i}] ${(sizeBytes / MIB).toFixed(0)} MiB sha256+md5 in ` +
            `${(r.wallMs / 1000).toFixed(1)}s — ${r.throughputMiBs.toFixed(1)} MiB/s`,
        );
      }
    }
  }

  console.log(
    JSON.stringify(
      {
        tool: "bench-hash.mjs",
        method:
          "Playwright-driven browser page; the app's real hash.worker.ts " +
          "bundled by esbuild (hash-wasm inlined) served as a same-origin " +
          "classic Worker over an intercepted route; Blob of generated " +
          "deterministic bytes, never on disk.",
        params: { sizeBytes, sliceBytes, repeat, browsers },
        results,
      },
      null,
      2,
    ),
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
